-- PT116-S3-Q12. Batch 05.
BEGIN;
DO $guard$ BEGIN IF NOT EXISTS (SELECT 1 FROM lr_questions q WHERE q.qid=$batch05$PT116-S3-Q12$batch05$ AND q.stimulus=$batch05$Some argue that because attaining governmental power in democracies requires building majority coalitions, it is a necessary evil that policymakers do not adhere rigorously to principle when dealing with important issues, but rather shift policies as they try to please different constituents at different times. But it is precisely this behavior that allows a democracy to adapt more easily to serve public interests, and thus it is more a benefit than an evil.$batch05$ AND q.prompt=$batch05$Which one of the following is an assumption required by the argument?$batch05$ AND q.correct_choice=$batch05$C$batch05$) THEN RAISE EXCEPTION 'Question changed: PT116-S3-Q12'; END IF; END $guard$;
DO $guard$ BEGIN IF (SELECT COUNT(*) FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id WHERE q.qid=$batch05$PT116-S3-Q12$batch05$ AND e.style IN ('single','standard')) <> 0 THEN RAISE EXCEPTION 'Explanation row changed: PT116-S3-Q12'; END IF; END $guard$;
INSERT INTO lr_explanations (question_id, style) SELECT q.id, 'single' FROM lr_questions q WHERE q.qid=$batch05$PT116-S3-Q12$batch05$ AND NOT EXISTS (SELECT 1 FROM lr_explanations e WHERE e.question_id=q.id AND e.style IN ('single','standard')) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_steps (explanation_id, position, label, body) SELECT e.id, v.position, v.label, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES (0, $batch05$Conclusion$batch05$, $batch05$Policymakers shifting their policies to please different groups is more a benefit than an evil.$batch05$), (1, $batch05$Evidence$batch05$, $batch05$That shifting is exactly what lets a democracy adapt to serve public interests.$batch05$), (2, $batch05$Evaluate$batch05$, $batch05$The author concedes there is a cost (no strict loyalty to principle) and names a benefit (adaptability). Then the author declares the benefit bigger. But nothing in the evidence weighs the two. Whenever an argument says "more X than Y," it needs X to outweigh Y, and that weighing is the gap.$batch05$), (3, $batch05$Goal$batch05$, $batch05$A link: the benefit of adaptability outweighs the cost of not sticking to principle.$batch05$)) v(position,label,body) WHERE q.qid=$batch05$PT116-S3-Q12$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_steps s WHERE s.explanation_id=e.id) ON CONFLICT DO NOTHING;
INSERT INTO lr_explanation_choice_notes (explanation_id, letter, body) SELECT e.id, v.letter, v.body FROM lr_explanations e JOIN lr_questions q ON q.id=e.question_id CROSS JOIN (VALUES ($batch05$A$batch05$, $batch05$The argument is about whether shifting is good on balance. It does not need policymakers to lose power over ignoring *any* faction.$batch05$), ($batch05$B$batch05$, $batch05$Democracies versus other governments never comes up. The author compares a benefit and a cost inside a democracy.$batch05$), ($batch05$C$batch05$, $batch05$This is the weighing, stated outright. Negate it: "the harm of abandoning principle outweighs the advantage of adaptability." Then shifting is more evil than benefit, the exact opposite of the conclusion.$batch05$), ($batch05$D$batch05$, $batch05$When policymakers appeal to principle is a different question from whether shifting is worth it.$batch05$), ($batch05$E$batch05$, $batch05$If democracies are not actually flexible, the benefit the author relies on disappears. An author never assumes something that sinks their own argument.$batch05$)) v(letter,body) WHERE q.qid=$batch05$PT116-S3-Q12$batch05$ AND e.style='single' AND NOT EXISTS (SELECT 1 FROM lr_explanation_choice_notes n WHERE n.explanation_id=e.id AND n.letter=v.letter) ON CONFLICT DO NOTHING;
